import pathlib
import warnings
from setuptools import setup, find_packages
from utils import parse_requirements, get_version

try:
    from builder.build import alternate_setup
except:
    alternate_setup = {}

DISTNAME = "kiutra-api"

DESCRIPTION = "A python package to interface with kiutra hardware."
URL = ""
LICENSE = "Apache Version 2.0 License"
LICENSES_FORMAT = 'csv'
LICENSES_FILE = 'LICENSES'
VERSION_FILE = '__version__.txt'
AUTHORS = [
    ('kiutra GmbH', 'support@kiutra.com')
]
YEAR = 2024

here = pathlib.Path(__file__).parent.resolve()
long_description = (here / "README.md").read_text(encoding="utf-8")

requires = parse_requirements('requirements.txt')
try:
    dev_requires = parse_requirements('requirements-dev.txt')
except Exception as e:
    warnings.warn(f"Failed to fetch dev requirements due to {e}")
    dev_requires = []

setup(
    name=DISTNAME,
    version=get_version(),
    description=DESCRIPTION,
    url=URL,
    license=LICENSE,
    license_files=('LICENSE.txt',),
    author=AUTHORS[0][0],
    author_email=AUTHORS[0][1],
    long_description=long_description,
    long_description_content_type="text/markdown",
    classifiers=[
        'Intended Audience :: Developers',
        'Intended Audience :: Science/Research',
        "License :: OSI Approved :: Apache Software License",
        'Operating System :: POSIX :: Linux',
        'Programming Language :: Python',
        'Topic :: Software Development :: Libraries :: Python Modules',
    ],
    cmdclass={
       **alternate_setup,
    },
    packages=find_packages(),
    include_package_data=True,
    package_data={
        DISTNAME:
            ['documentation/html', 'documentation/pdf'],
    },
    install_requires=requires,
    extras_require={
        "dev": dev_requires,
    },
    python_requires='>=3.7,<3.12',
)

